// 모델은 환경변수로 교체 가능 (Vercel: REPORT_MODEL).
const MODEL = process.env.REPORT_MODEL || "claude-sonnet-5";

const LANG_NAME: Record<Lang, string> = {
  th: "Thai", en: "English", ko: "Korean",
};

interface AnthropicLike {
  messages: {
    create(args: unknown): Promise<{ content: Array<{ type: string; text?: string }> }>;
  };
}

let client: AnthropicLike | null | undefined;
function getClient(): AnthropicLike | null {
  if (client !== undefined) return client;
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) {
    client = null;
    return null;
  }
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const Anthropic = require("@anthropic-ai/sdk");
  client = new Anthropic({ apiKey: key }) as AnthropicLike;
  return client;
}

/** Tiny live-fire test of the generation stack — surfaces the exact API error. */
export async function generationHealth(): Promise<{
  ok: boolean;
  model: string;
  error?: string;
}> {
  try {
    const c = getClient();
    if (!c) return { ok: false, model: MODEL, error: "ANTHROPIC_API_KEY not set" };
    const res = await c.messages.create({
      model: MODEL,
      max_tokens: 16,
      messages: [{ role: "user", content: "ping — reply with pong only" }],
    });
    const text = res.content.find((b) => b.type === "text")?.text ?? "";
    return { ok: text.length > 0, model: MODEL };
  } catch (err) {
    return { ok: false, model: MODEL, error: String(err).slice(0, 400) };
  }
}

function pillarsOf(c: SajuChart): string {
  const p = (x: { gan: string; zhi: string } | null) => (x ? x.gan + x.zhi : "미상");
  return `시주 ${p(c.hour)} / 일주 ${p(c.day)} / 월주 ${p(c.month)} / 연주 ${p(c.year)}`;
}

function birthOf(c: SajuChart): { year: number; month: number; day: number } {
  return { year: c.solarUsed.y, month: c.solarUsed.m, day: c.solarUsed.d };
}

