// 점수 → 표현 구간. AI는 이 구간 표현과 같은 방향으로만 서술한다.
function band(score: number, low: string, mid: string, high: string): string {
  return score >= 70 ? high : score >= 40 ? mid : low;
}

function chunk<T>(arr: T[], size: number): T[][] {
  const out: T[][] = [];
  for (let i = 0; i < arr.length; i += size) out.push(arr.slice(i, i + size));
  return out;
}

// 모델 출력에서 [{title, body}] 를 최대한 살려낸다: 코드펜스, 배열 대신 객체 하나,
// max_tokens 로 끝이 잘린 JSON 까지 처리.
function parseSections(raw: string): Array<{ title: string; body: string }> | null {
  const text = raw.replace(/```(?:json)?/g, "").trim();
  const tryParse = (s: string): unknown => {
    try {
      return JSON.parse(s);
    } catch {
      return undefined;
    }
  };
  const a = text.indexOf("["), b = text.lastIndexOf("]");
  if (a >= 0 && b > a) {
    const v = tryParse(text.slice(a, b + 1));
    if (Array.isArray(v)) return v as Array<{ title: string; body: string }>;
  }
  const o = text.indexOf("{"), oe = text.lastIndexOf("}");
  if (o >= 0 && oe > o) {
    const v = tryParse(text.slice(o, oe + 1)) as { title?: string; body?: string } | undefined;
    if (v && typeof v.title === "string" && typeof v.body === "string") return [{ title: v.title, body: v.body }];
  }
  // 잘린 JSON: "title":"…" 와 "body":"… (닫는 따옴표 없을 수 있음)
  const t = text.match(/"title"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  const bm = text.match(/"body"\s*:\s*"((?:[^"\\]|\\.)*)/);
  if (t && bm) {
    const unesc = (s: string) => tryParse(`"${s.replace(/\\$/, "")}"`) as string | undefined;
    const title = unesc(t[1]);
    let body = unesc(bm[1]) ?? bm[1].replace(/\\n/g, "\n");
    if (title && body) {
      // 문장 중간에서 잘렸으면 마지막 완결 문단/문장까지만.
      const cut = Math.max(body.lastIndexOf("\n\n"), body.lastIndexOf("ค่ะ"), body.lastIndexOf(". "), body.lastIndexOf("요."));
      if (cut > body.length * 0.6) body = body.slice(0, cut + (body.startsWith("ค่ะ", cut) ? 3 : 2)).trim();
      return [{ title, body }];
    }
  }
  return null;
}

// One generation call for a slice of categories. Chunked + parallel so the
// full 12-13 category long-form report fits serverless time limits.
async function callChunk(
  c: AnthropicLike,
  system: string,
  context: string,
  cats: ReportCategory[],
  allCats: ReportCategory[],
  startNo: number,
  lang: Lang,
  ignoreNames: string[] = []
): Promise<Array<{ title: string; body: string }> | null> {
  const prompt =
    context +
    `\n\n전체 리포트의 카테고리 구성 (겹치면 안 되는 다른 주제들):\n` +
    allCats.map((t, i) => `${i + 1}. ${t.label}`).join(" / ") +
    `\n\n이번엔 다음 카테고리만 작성해줘:\n` +
    cats.map((t, i) => `${startNo + i}. [${t.label}] ${t.spec}`).join("\n") +
    `\n\n범위 규칙: 위 [라벨]의 spec 범위 안에서만 써라. 전체 구성에 있는 다른 카테고리의 ` +
    `주제는 여기서 한 문장도 다루지 마라 (예: 겉궁합에서 속궁합 얘기 금지, 결혼운에서 돈 얘기 금지). ` +
    `\n\n${LENGTH_RULE}\n\n출력은 반드시 JSON 배열만: [{"title":"...","body":"..."}] — ` +
    `title은 반드시 "<카테고리명> — <감성 부제>" 형식 (카테고리명은 [라벨]을 ${LANG_NAME[lang]}로, ` +
    `부제는 이 커플만의 한 줄). 번호는 붙이지 마라. body는 본문. ` +
    `모든 텍스트는 ${LANG_NAME[lang]}(으)로.`;
  try {
    const res = await c.messages.create({
      model: MODEL,
      max_tokens: 6000,
      system: [{ type: "text", text: system, cache_control: { type: "ephemeral" } }],
      messages: [{ role: "user", content: prompt }],
    });
    const text = res.content.find((b) => b.type === "text")?.text ?? "";
    const parsed = parseSections(text);
    if (!parsed || parsed.length === 0) {
      console.warn("report chunk unparseable", { stop: (res as { stop_reason?: string }).stop_reason, len: text.length });
      return null;
    }
    const out = parsed.map((sec) => ({
      title: normalizeHanja(String(sec.title ?? ""), lang).slice(0, 120),
      body: normalizeHanja(String(sec.body ?? ""), lang),
    }));
    // Reject degenerate output — a rare "placeholder" stub, an empty body, or a
    // section far shorter than the length rule asks for. Returning null lets the
    // caller's retry loop regenerate this part instead of saving junk.
    if (out.some((s) => s.body.trim().length < 120 || s.body.trim() === s.title.trim())) {
      return null;
    }
    const stripNames = (t: string) => ignoreNames.filter(Boolean).reduce((acc, n) => acc.split(n).join(""), t);
    if (out.some((s) => wrongLanguage(stripNames(s.title + " " + s.body), lang))) {
      console.warn("report chunk in wrong language — retrying");
      return null;
    }
    return out;
  } catch (err) {
    console.error("report chunk generation failed:", err);
    return null;
  }
}

const THAI_NAMING =
  ` 태국어 표기 규칙: 지지는 한자 음역(เจี๊ยะ·ฮว่าย·แก้ 등)을 쓰지 말고 태국 12지 이름으로 ` +
  `(子ชวด 丑ฉลู 寅ขาล 卯เถาะ 辰มะโรง 巳มะเส็ง 午มะเมีย 未มะแม 申วอก 酉ระกา 戌จอ 亥กุน), ` +
  `천간은 오행으로 풀어 써라(예: 丙 = ไฟหยาง/ดวงอาทิตย์). 간지 한자는 괄호 안에만 둔다. ` +
  `한국어 문장·한국어 제목을 쓰지 마라(명리 용어는 괄호 안 한글 1~2단어만 허용).`;

// 언어별 표기 규칙: 본문에 한자만 덩그러니 쓰지 않고 각 언어로 풀어 쓴다.
function scriptRules(lang: Lang): string {
  if (lang === "th") return THAI_NAMING +
    ` 십신·신살·12운성도 태국어 뜻으로 풀어 써라(예: 식신 → ดาวแห่งการสร้างสรรค์, 천을귀인 → ดาวผู้อุปถัมภ์). 신살 태국어 이름은 사이트 카드와 똑같이 고정: 도화살 → ดาวเสน่ห์, 홍염살 → ดาวเสน่หายั่วใจ, 화개살 → ดาวศิลปะ, 역마살 → ดาวการเดินทาง, 문창귀인 → ดาวปัญญา, 백호살 → ดาวเสือขาว, 괴강살 → ดาวผู้นำ, 양인살 → พลังนักสู้, 원진살 → ดาวใจละเอียด (한자 음역 금지, 예: โต๊ะฮวย ✗). ` +
    `한자(丙戌·食神·白虎殺 등)를 문장 안에 단독으로 쓰지 마라. 꼭 필요하면 태국어 뒤 괄호 안에 섹션당 1회만.`;
  if (lang === "en") return ` Script rule: write every term in English (e.g. "Byeong-sul day pillar", "Output star (Siksin)", "White Tiger star"). ` +
    `Never drop bare Chinese characters (丙戌, 食神, 白虎殺) into a sentence; at most once per section in parentheses after the English.`;
  return ` 한자 표기 규칙: 본문은 한글로 쓴다. 간지·십신·신살은 한글로(병술 일주, 계해 월주, 식신, 일지, 백호살, 화개살, 천을귀인). ` +
    `한자를 단독으로 쓰지 마라(丙戌 일주 ✗, 食神 ✗, 白虎殺 ✗ → 병술 일주, 식신, 백호살). 꼭 필요하면 한글 뒤 괄호 안에 섹션당 처음 1회만(예: 병술(丙戌)).`;
}

// 괄호 밖에 한자가 많이 남은 섹션은 재시도시킨다 (정리 후에도 남은 경우만).
function tooMuchHanja(text: string): boolean {
  const outside = text.replace(/\([^)]*\)/g, "");
  return (outside.match(/[\u4E00-\u9FFF]/g) ?? []).length > 12;
}

// 한자 → 한글 독음 (명리 용어에 쓰이는 글자).
const HANJA_KO: Record<string, string> = {
  甲: "갑", 乙: "을", 丙: "병", 丁: "정", 戊: "무", 己: "기", 庚: "경", 辛: "신", 壬: "임", 癸: "계",
  子: "자", 丑: "축", 寅: "인", 卯: "묘", 辰: "진", 巳: "사", 午: "오", 未: "미", 申: "신", 酉: "유", 戌: "술", 亥: "해",
  木: "목", 火: "화", 土: "토", 金: "금", 水: "수",
  食: "식", 神: "신", 傷: "상", 官: "관", 正: "정", 偏: "편", 印: "인", 財: "재", 劫: "겁", 比: "비", 肩: "견",
  殺: "살", 煞: "살", 墓: "묘", 合: "합", 化: "화", 沖: "충", 冲: "충", 刑: "형", 破: "파", 害: "해",
  天: "천", 貴: "귀", 人: "인", 華: "화", 蓋: "개", 白: "백", 虎: "호", 桃: "도", 花: "화", 紅: "홍", 艶: "염",
  驛: "역", 馬: "마", 魁: "괴", 罡: "강", 羊: "양", 刃: "인", 怨: "원", 嗔: "진", 文: "문", 昌: "창",
  日: "일", 月: "월", 時: "시", 年: "년", 柱: "주", 支: "지", 干: "간", 大: "대", 運: "운", 歲: "세",
  身: "신", 強: "강", 弱: "약", 用: "용", 喜: "희", 忌: "기", 格: "격", 調: "조", 候: "후", 生: "생", 旺: "왕",
  帝: "제", 冠: "관", 帶: "대", 長: "장", 浴: "욕", 衰: "쇠", 病: "병", 死: "사", 絶: "절", 胎: "태", 養: "양",
};

/**
 * 괄호 밖의 한자를 언어에 맞게 정리한다.
 * ko: 한글 독음으로 바꾼다(丙戌 → 병술). th·en: 괄호로 감싸 보조 표기로 돌린다(丙戌 → (丙戌)).
 */
function normalizeHanja(text: string, lang: Lang): string {
  return text
    .split(/(\([^)]*\))/g)
    .map((seg) => {
      if (seg.startsWith("(")) return seg;
      return seg.replace(/[\u4E00-\u9FFF]+/g, (run) => {
        if (lang === "ko") {
          const ko = [...run].map((ch) => HANJA_KO[ch] ?? ch).join("");
          return /[\u4E00-\u9FFF]/.test(ko) ? `(${run})` : ko;
        }
        return ` (${run}) `;
      });
    })
    .join("")
    .replace(/ {2,}/g, " ")
    .replace(/ \)/g, ")")
    .replace(/\( /g, "(");
}

// 출력 언어 검사: 다른 언어(특히 한국어)로 써버린 섹션은 버리고 재시도시킨다.
function wrongLanguage(text: string, lang: Lang): boolean {
  if (tooMuchHanja(text)) return true;
  // 괄호 안 보조 표기(한자·한글 용어)는 비율 계산에서 뺀다.
  const letters = text.replace(/\([^)]*\)/g, "").replace(/[\s\d\p{P}\p{S}]/gu, "");
  if (!letters) return true;
  const hangul = (letters.match(/[\uAC00-\uD7A3]/g) ?? []).length;
  const thai = (letters.match(/[\u0E00-\u0E7F]/g) ?? []).length;
  if (lang === "th") return thai / letters.length < 0.5 || hangul / letters.length > 0.12;
  if (lang === "en") return hangul / letters.length > 0.12 || thai / letters.length > 0.12;
  return hangul / letters.length < 0.3; // ko
}

/**
 * Translate ONE generated section into another language, preserving meaning,
 * length, paragraph breaks, and emoji — so every language shows the same
 * report. Client-orchestrated one call per section (like generation).
 */
export async function translateSection(
  title: string,
  body: string,
  lang: Lang
): Promise<{ title: string; body: string } | null> {
  const c = getClient();
  if (!c) return null;
  const prompt =
    `다음 사주 해석 섹션을 ${LANG_NAME[lang]}(으)로 번역해줘. ` +
    `의미와 정보량, 문단 구분(빈 줄), 이모지를 그대로 유지하고, ` +
    `명리 용어는 ${LANG_NAME[lang]} 독자가 이해할 수 있게 자연스럽게 옮겨라. 요약하거나 줄이지 마라.` + scriptRules(lang) + ` ` +
    `출력은 반드시 JSON 하나만: {"title":"...","body":"..."}\n\n` +
    `[제목] ${title}\n[본문]\n${body}`;
  try {
    const res = await c.messages.create({
      model: MODEL,
      max_tokens: 3000,
      messages: [{ role: "user", content: prompt }],
    });
    const text = res.content.find((b) => b.type === "text")?.text ?? "";
    const json = text.slice(text.indexOf("{"), text.lastIndexOf("}") + 1);
    const p = JSON.parse(json) as { title: string; body: string };
    if (!p?.title || !p?.body) return null;
    // Reject a degenerate/placeholder translation so the retry loop re-runs it.
    if (String(p.body).trim().length < 120) return null;
    const tt = normalizeHanja(String(p.title), lang);
    const tb = normalizeHanja(String(p.body), lang);
    if (wrongLanguage(tt + " " + tb, lang)) return null;
    return { title: tt.slice(0, 200), body: tb };
  } catch (err) {
    console.error("section translation failed:", err);
    return null;
  }
}

